{"command": "cd /workspace && python3 -c "
import subprocess
esc=[]
notesc=[]
for i in range(1,128):
    c=chr(i)
    if c in '\"': continue
    p=subprocess.run(['./executable','a'+c+'b'],capture_output=True,text=True)
    out=p.stdout.strip()
    # output format ^a?b$ ; find what c became
    inner=out[1:-1]
    exp = inner[1:-1] if inner.startswith('a') and inner.endswith('b') else None
    if exp is None:
        print('???', i, repr(c), out); continue
    if exp != c: esc.append((i,repr(c),exp))
    else: notesc.append((i,repr(c)))
print('ESCAPED:'); 
for e in esc: print(' ',e)
print('NOT ESCAPED:')
print(' ', ' '.join(x[1] for x in notesc))
""}

